const Imap = require('imap');

const originalMessageId = $input.first().json.message_id;
const reply_message_id = $input.first().json.reply_message_id;

const imapHost = $input.first().json.imap_host;
const imapPort = $input.first().json.imap_port;
const imapUser = $input.first().json.imap_user;
const imapPass = $input.first().json.imap_pass;

const to = $input.first().json.sender;
const subject = $input.first().json.subject;
const body = $input.first().json.textHtml;
const answer = $input.first().json.answer

// Преобразование даты и время
const rawDate = $input.first().json.date;
const dateObj = new Date(rawDate);

// Добавляем +3 часа (Москва)
dateObj.setHours(dateObj.getHours() + 3);
// Форматируем дату: дд.мм.гггг
const localDate = dateObj.toLocaleDateString('ru-RU'); // → 03.07.2025
// Форматируем время: чч:мм (без секунд)
const localTime = dateObj.toLocaleTimeString('ru-RU', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false, // или true, если нужно 12ч формат
});


const html = `
<div>${answer}</div>
<div> </div>
<div>----------------</div>
<div>Кому: ${to} (${to});</div>
<div>Тема: ${subject};</div>
<div>${localDate}, ${localTime}, "${to}" &lt;${to}&gt;:</div>
<blockquote>
  ${body}
</blockquote>
`;

function normalizeMessageId(id) {
  return id.startsWith('<') ? id : `<${id}>`;
}

function saveEmail() {
  return new Promise((resolve, reject) => {
    try {
      const imap = new Imap({
        user: imapUser,
        password: imapPass,
        host: imapHost,
        port: imapPort,
        tls: true,
      });

      const encodedSubject = `=?UTF-8?B?${Buffer.from(`Re: ${subject}`).toString('base64')}?=`;

      imap.once('ready', function () {
        const rawMessage = [
          `From: ${imapUser}`,
          `To: ${to}`,
          `Subject: ${encodedSubject}`,
          `Date: ${new Date().toUTCString()}`,
          `Message-ID: ${normalizeMessageId(reply_message_id)}`,
          `In-Reply-To: ${normalizeMessageId(originalMessageId)}`,
          `References: ${normalizeMessageId(originalMessageId)}`,
          `MIME-Version: 1.0`,
          `Content-Type: text/html; charset=UTF-8`,
          `Content-Transfer-Encoding: 7bit`,
          '',
          html,
        ].join('\r\n');

        const sentFolder = 'Рассылки|Отправленные';
        let res;
        imap.append(rawMessage, { mailbox: sentFolder, flags: ['\\Seen'] }, function (err) {
          if (err) {
            console.log('❌ Ошибка при сохранении в "Отправленные":', err);
            res = false;
          } else {
            console.log('📩 Скопировано в "Отправленные"');
            res = true;
          }
          imap.end();
          resolve(res);
        });
      });

      imap.once('error', function (err) {
        console.log('IMAP ошибка:', err);
        resolve(false);
      });

      imap.connect();
    } catch (err) {
      console.log('🚨 Исключение при соединении с IMAP:', err);
      resolve(false);
    }
  });
}


const res = await saveEmail();
$input.first().json.imap = res;
return $input.first().json;

