const smtpHost = $input.first().json.smtp_host;
const smtpPort = $input.first().json.smtp_port;
const smtpUser = $input.first().json.smtp_user;
const smtpPass = $input.first().json.smtp_pass;

const to = $input.first().json.sender;
const subject = $input.first().json.subject;
const body = $input.first().json.textHtml;
const answer = $input.first().json.answer

// Преобразование даты
const rawDate = $input.first().json.date;
const dateObj = new Date(rawDate);

// Добавляем +3 часа (Москва)
dateObj.setHours(dateObj.getHours() + 3);
// Форматируем дату: дд.мм.гггг
const localDate = dateObj.toLocaleDateString('ru-RU'); // → 03.07.2025
// Форматируем время: чч:мм (без секунд)
const localTime = dateObj.toLocaleTimeString('ru-RU', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false, // или true, если нужно 12ч формат
});

const html = `
<div>${answer}</div>
<div> </div>
<div>----------------</div>
<div>Кому: ${to} (${to});</div>
<div>Тема: ${subject};</div>
<div>${localDate}, ${localTime}, "${to}" &lt;${to}&gt;:</div>
<blockquote>
  ${body}
</blockquote>
`;

function normalizeMessageId(id) {
  return id.startsWith('<') ? id : `<${id}>`;
}

async function sendEmail() {
  const transporter = nodemailer.createTransport({
    host: smtpHost,
    port: smtpPort,
    secure: true,
    auth: {
      user: smtpUser,
      pass: smtpPass,
    },
  });

  const message = {
    from: smtpUser,
    to,
    subject: subject.startsWith("Re:") ? subject : `Re: ${subject}`,
    html,
    inReplyTo: normalizeMessageId(originalMessageId),
    references: [normalizeMessageId(originalMessageId)],
    headers: {
      // Уведомление о доставке
      'Disposition-Notification-To': smtpUser,

      // Уведомление о прочтении
      'Return-Receipt-To': smtpUser,
      'X-Confirm-Reading-To': smtpUser,

      // Об ошибках доставки
      'Errors-To': smtpUser,
    }
  };

  try {
    const info = await transporter.sendMail(message);

    if (
      info.accepted.includes(to) &&
      (!info.rejected || info.rejected.length === 0)
    ) {
      console.log('✅ Письмо успешно отправлено:', info.messageId);
      return String(info.messageId);;
    } else {
      console.log('❌ Ошибка: письмо не принято сервером.');
      console.log('Ответ SMTP:', info.response);
      console.log('Отказано адресам:', info.rejected);
      return -1;
    }
  } catch (err) {
    console.log('🚨 Исключение при отправке SMTP:', err);
    return -1;
  }
  return -1;
}

const reply_message_id = await sendEmail();

if (reply_message_id == -1){
  $input.first().json.smtp = false;
} else {
  $input.first().json.reply_message_id = reply_message_id;
  $input.first().json.smtp = true;
}

return $input.first().json;

